def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/noaa_wildfires_variabledescrip.csv'
    # Try common encodings used in NOAA/docs exports
    for enc in ['cp1252', 'latin1', 'utf-8']:
        try:
            df = pd.read_csv(path, encoding=enc)
            break
        except UnicodeDecodeError:
            df = None
    if df is None:
        # last resort: ignore errors
        df = pd.read_csv(path, encoding='utf-8', errors='ignore')
    return pd.concat([df.head(5), df.tail(5)], ignore_index=True)

