def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/noaa_wildfires.csv'
    df = pd.read_csv(path)

    # Parse dates if present
    for c in ['start_date', 'controlled_date']:
        if c in df.columns:
            df[c] = pd.to_datetime(df[c], errors='coerce', infer_datetime_format=True)

    # Coerce key numeric columns
    for c in ['hec', 'wind_med']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')

    return df
